head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > showCustomFilter2]<br/>Header Column 의 ID 를 사용하여 특정 Column 에서 CustomFilter 팝업창을 표시합니다.",
    "validation" : [
        "useFilter, useFilterList, headerFilter 속성 및 GroupBy 상태 등을 무시하고 즉시 CustomFilter 기능을 실행합니다.",
        "headerId(필수) 파라미터로 CustomFilter 팝업창을 표시할 Header Column 의 ID 를 설정합니다.",
        "CustomFilter 팝업창에서 설정한 필터값이 Column 에 적용되어 필터링이 실행됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - useFilter / headerFilter 속성 없이도 showCustomFilter2 가 즉시 CustomFilter 팝업을 표시함을 보이기 위해
//    일반 커스텀 gridView 를 동적 생성 (Header Column 에 id 명시 → getColIdByHeaderId 매핑)
//  - Header Column ID : hcol_name / hcol_dept / hcol_pos / hcol_memo (par_headerId 항목)
//  - Body Column ID   : name / dept / pos / memo (매핑 대상)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제 (Target 재생성으로 팝업 등 상태 초기화)
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 상태 참고 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] useFilter/headerFilter 없이 동작\n[전제] Header Column ID : hcol_name, hcol_dept, hcol_pos, hcol_memo\n[절차] par_headerId 선택 -> showCustomFilter2(팝업) -> 팝업 입력창에 필터값 입력 후 OK -> 필터 결과 확인 버튼\n[확인] 팝업 표시(대상 컬럼) + 필터 적용 후 표시된 값(걸러진 결과)"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="pos" name="pos" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "dept": "영업", "pos": "부장", "memo": "메모0" },
        { "name": "Jane", "dept": "기획", "pos": "차장", "memo": "메모1" },
        { "name": "Mike", "dept": "개발", "pos": "과장", "memo": "메모2" },
        { "name": "Sara", "dept": "영업", "pos": "대리", "memo": "메모3" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 (useFilter/headerFilter 등은 설정하지 않음)
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (마지막 memo Column width="*" 로 가로 스크롤 방지)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:520px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="showCustomFilter2 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol_name" value="이름"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol_dept" value="부서"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol_pos" value="직급"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_memo" value="메모"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="pos" dataList="pos"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// showCustomFilter2 실행 : par_headerId(Header Column ID) 로 호출
//  - useFilterList/GroupBy/headerFilter 분기를 건너뛰고 즉시 해당 컬럼에 CustomFilter 팝업 표시
//  - 팝업 표시 여부(.w2grid_customFilter 존재) + 대상 headerID / 매핑 Body Column(targetColID) 출력
//    (팝업 내 필터값 입력/OK 클릭은 사용자/자동화가 팝업 UI 를 직접 조작 → 별도 입력/OK 버튼은 생성하지 않음)
scwin.btn_showCustomFilter2_onclick = function () {
    let headerId = par_headerId.getValue();

    // 이전 케이스에서 잔존한 CustomFilter 팝업 정리 (새 팝업만 확인)
    let oldPopups = document.querySelectorAll('.w2grid_customFilter');
    for (let i = 0; i < oldPopups.length; i++) {
        oldPopups[i].remove();
    }

    // Header Column ID 로 CustomFilter 팝업 즉시 표시
    target1.showCustomFilter2(headerId);

    let popup = document.querySelector('.w2grid_customFilter');
    wf_body_bottom.getObj("scwin").setReturnValue("showCustomFilter2(" + headerId + ") CustomFilter 팝업 표시 : " + (popup !== null));
    wf_body_bottom.getObj("scwin").setReturnValue("표시 대상 headerID : " + target1.headerID + " / 매핑 Body Column(targetColID) : " + target1.targetColID);
}



// 필터 결과 확인 : 팝업에서 필터값 입력 후 OK 로 적용된 결과를 검증
//  - showCustomFilter2 로 팝업을 연 대상 컬럼(targetColID)에 대해
//    현재 그리드에 표시된(필터로 걸러진) 행 수와 대상 컬럼 값을 읽어 출력
//  - getRowCount() 는 필터 적용 후 표시 행 수를, getCellData(i, colId) 는 표시된 행의 값을 반환
scwin.btn_checkFilterResult_onclick = function () {
    let colId = target1.targetColID;
    if (!colId) {
        wf_body_bottom.getObj("scwin").setReturnValue("먼저 par_headerId 선택 후 showCustomFilter2 실행 및 팝업에서 필터 적용(OK)하세요.");
        return;
    }

    let cnt = target1.getRowCount();
    let vals = [];
    for (let i = 0; i < cnt; i++) {
        vals.push(target1.getCellData(i, colId));
    }
    wf_body_bottom.getObj("scwin").setReturnValue("필터 적용 후 표시 행 수 : " + cnt + " / 표시된 " + colId + " 값 : " + vals.join(", "));
}
